/**
 * S-04a-1b build step. Assembles the throwaway probe extension for Chrome MV3.
 *
 * The micro graphs are a few KB each, so they are packaged as extension resources alongside
 * ORT's .wasm artifacts. Nothing here is committed: the graphs are generated by
 * build_micro.py and the wasm files come from the pinned npm package.
 */
const fs = require("fs");
const path = require("path");

const DIST = path.join(__dirname, "node_modules", "onnxruntime-web", "dist");
const OUT = path.join(__dirname, "ext-chrome");
const MICRO = path.join(__dirname, "micro");

const NEEDED = [
  "ort.all.min.js",
  "ort-wasm-simd-threaded.mjs",
  "ort-wasm-simd-threaded.wasm",
  "ort-wasm-simd-threaded.jsep.mjs",
  "ort-wasm-simd-threaded.jsep.wasm",
];

fs.mkdirSync(OUT, { recursive: true });
fs.mkdirSync(path.join(OUT, "micro"), { recursive: true });
for (const f of NEEDED) {
  const src = path.join(DIST, f);
  if (!fs.existsSync(src)) { console.error("MISSING in dist:", f); process.exit(1); }
  fs.copyFileSync(src, path.join(OUT, f));
}
for (const f of fs.readdirSync(MICRO)) {
  fs.copyFileSync(path.join(MICRO, f), path.join(OUT, "micro", f));
}

const reference = fs.readFileSync(path.join(__dirname, "micro-reference.json"), "utf8");
const specs = fs.readFileSync(path.join(__dirname, "micro-specs.json"), "utf8");
let probe = fs.readFileSync(path.join(__dirname, "micro-probe.js"), "utf8")
  .replace("__MICRO_REFERENCE_JSON__", reference)
  .replace("__MICRO_SPECS_JSON__", specs);

// Optional: the layer-wise probe for the real model, appended when LAYERWISE=1.
if (process.env.LAYERWISE) {
  probe += "\n" + fs.readFileSync(path.join(__dirname, "layer-probe.js"), "utf8");
  const lref = path.join(__dirname, "layer-reference.json");
  if (fs.existsSync(lref)) {
    probe = probe.replace("__LAYER_REFERENCE_JSON__", fs.readFileSync(lref, "utf8"));
  }
  // the sliced model is packaged as a resource
  const sliced = path.join(__dirname, "sliced");
  if (fs.existsSync(sliced)) {
    fs.mkdirSync(path.join(OUT, "sliced"), { recursive: true });
    for (const f of fs.readdirSync(sliced)) {
      fs.copyFileSync(path.join(sliced, f), path.join(OUT, "sliced", f));
    }
  }
}
fs.writeFileSync(path.join(OUT, "probe.js"), probe);

const BACKENDS = (process.env.BACKENDS || "wasm,webgpu").split(",");

fs.writeFileSync(path.join(OUT, "manifest.json"), JSON.stringify({
  manifest_version: 3,
  name: "PratiBimb S-04a-1b WebGPU int8 root-cause probe",
  version: "1.0.0",
  description: "Throwaway spike harness. Minimal int8 graphs, wasm vs webgpu.",
  minimum_chrome_version: "116",
  background: { service_worker: "background.js" },
  permissions: ["offscreen"],
  host_permissions: ["http://127.0.0.1:8909/*"],
  _csp_note:
    "S-02a-2b measured that Chrome MV3 blocks WebAssembly without this and that " +
    "'wasm-unsafe-eval' is the only token it accepts. THROWAWAY HARNESS ONLY. Not adopted " +
    "in any product manifest -- the decision is ADR S-02a-2a.",
  content_security_policy: { extension_pages: "script-src 'self' 'wasm-unsafe-eval'; object-src 'self'" },
}, null, 2));

fs.writeFileSync(path.join(OUT, "offscreen.html"),
  '<!doctype html><meta charset="utf-8"><title>s04a1b offscreen</title>' +
  '<script src="ort.all.min.js"></script><script src="probe.js"></script><script src="offscreen.js"></script>');

fs.writeFileSync(path.join(OUT, "offscreen.js"), [
  'chrome.runtime.onMessage.addListener((msg) => {',
  '  if (!msg || msg.type !== "s04a1b-go") return;',
  '  (async () => {',
  '    const base = chrome.runtime.getURL("");',
  '    const results = [];',
  '    for (const backend of ' + JSON.stringify(BACKENDS) + ') {',
  '      results.push(await globalThis.runMicroProbe("chrome-offscreen-document", { backend, wasmPaths: base, modelBase: base, numThreads: 1 }));',
  '      if (globalThis.runLayerProbe) {',
  '        for (const optLevel of ' + JSON.stringify((process.env.OPT_LEVELS || "all").split(",")) + ') {',
  '          for (const modelFile of ' + JSON.stringify((process.env.MODEL_FILES || "sliced/vision_encoder_int8_instrumented.onnx").split(",")) + ') {',
  '            results.push(await globalThis.runLayerProbe("chrome-offscreen-document", { backend, optLevel, modelFile, wasmPaths: base, modelBase: base, numThreads: 1 }));',
  '          }',
  '        }',
  '      }',
  '    }',
  '    chrome.runtime.sendMessage({ type: "s04a1b-results", results });',
  '  })();',
  '});',
].join("\n"));

fs.writeFileSync(path.join(OUT, "background.js"), [
  'const BASE = "http://127.0.0.1:8909";',
  'async function ensureOffscreen() {',
  '  const has = await chrome.runtime.getContexts({ contextTypes: ["OFFSCREEN_DOCUMENT"] });',
  '  if (has.length) return;',
  '  await chrome.offscreen.createDocument({ url: "offscreen.html", reasons: ["WORKERS"], justification: "S-04a-1b int8 root-cause probe" });',
  '}',
  'globalThis.__s04a1b_run = async function () {',
  '  await ensureOffscreen();',
  '  const res = await new Promise((resolve) => {',
  '    const t = setTimeout(() => resolve([{ context: "chrome-offscreen-document", conclusion: "offscreen timeout" }]), 3600000);',
  '    chrome.runtime.onMessage.addListener(function h(m) {',
  '      if (m && m.type === "s04a1b-results") { clearTimeout(t); chrome.runtime.onMessage.removeListener(h); resolve(m.results); }',
  '    });',
  '    chrome.runtime.sendMessage({ type: "s04a1b-go" }).catch(() => {});',
  '  });',
  '  try {',
  '    await fetch(BASE + "/result", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ contexts: res }) });',
  '  } catch (e) {}',
  '  return res;',
  '};',
].join("\n"));

console.log("built ext-chrome; backends:", BACKENDS.join(","), "layerwise:", !!process.env.LAYERWISE);
